3: // =============================================================================
4: // ShadowMode=3 : "protect the light-space matrix".
5: //
6: // Root cause (production d3d9.cpp, StereoPairBody ~L10992):
7: //   The stereo path does not translate geometry. It collects every constant
8: //   register that currently holds a camera matrix and re-uploads a PER-EYE
9: //   version of it (ApplyEyeRemap: clip-space half-width + eye offset). That is
10: //   correct for the camera view/projection. It is catastrophic for a
11: //   light-space (shadow) projection matrix that happens to land in the same
12: //   register set - the shadow lookup is then shifted/squashed per eye, which is
13: //   exactly the reported "blocky, flickering, one eye darker, different per
14: //   eye" behaviour. The production comment already names the register reuse:
15: //   "the same register is reused by shadow and post passes with different
16: //   [meaning]".
17: //
18: // The fix is a classification/policy, not new shadow rendering:
19: //   1. a light-space / shadow-map generation draw is drawn ONCE, native, and is
20: //      never split or remapped (this is the Dishonored-VR/DX9 rule: render
21: //      target identity beats a matrix-register hit; never split a shadow map);
22: //   2. a light-space projection register is NEVER included in the per-eye
23: //      camera remap, so both eyes sample the same shadow coordinates for the
24: //      same world point;
25: //   3. anything the policy cannot classify is drawn mono (never split), which
26: //      keeps the existing anti-flicker fallback.
27: //
28: // The register census is filled from live evidence (shader-declares-shadow, or
29: // a projected-shadow texture bound), never guessed. See docs/SHADOW_MODE3.md.
30: // =============================================================================
31: 
32: #include "shadow_pass_policy.h"
33: 
34: #include <cstdint>
35: 
36: namespace singularity::shadow {
37: 
38: // --- per-draw decision at the StereoPair seam -------------------------------
39: 
40: struct DrawEvidence {
41:     bool layoutShadow = false;        // shader declares ProjectionMatrix + DepthBias
42:     bool shadowMapBound = false;      // a projected-shadow texture is bound to this draw
43:     bool offscreenDepthOnly = false;  // drawing into the light-space shadow target
44:     bool isScene = true;              // true = scene/receiver target, false = offscreen
45:     bool knownCameraSlot = false;     // at least one live camera matrix register
46:     bool finite = true;               // near/far/matrices were all finite
47: };
48: 
49: // Named StereoAction to avoid colliding with shadow_pass_policy.h's DrawAction.
50: enum class StereoAction : std::uint8_t {
51:     StereoEye,         // per-eye camera remap, split per eye
52:     NativeShadowOnce,  // draw once, native, never split/remapped
53:     MonoFallback,      // unknown -> one unsplit draw (the anti-flicker fallback)
54: };
55: 
56: inline StereoAction DecideDraw(const DrawEvidence& e) {
57:     if (!e.finite) return StereoAction::MonoFallback;
58:     if (e.layoutShadow || e.offscreenDepthOnly) return StereoAction::NativeShadowOnce;
59:     if (!e.isScene) return StereoAction::NativeShadowOnce;
60:     if (e.knownCameraSlot) return StereoAction::StereoEye;
61:     return StereoAction::MonoFallback;
62: }
63: 
64: // The one-line fix, unit-tested: a shadow (light-space) matrix register is
65: // excluded from the per-eye camera remap.
66: inline bool ShouldRemapRegister(bool isCameraMatrix, bool isShadowMatrix) {
67:     return isCameraMatrix && !isShadowMatrix;
68: }
69: 
70: // --- live census of which constant slots hold a light-space matrix ----------
71: // Filled by the hook (never by this header). Bit s set => slot s is a shadow
72: // projection and must not be remapped.
73: class ShadowRegisterCensus {
74: public:
75:     void Clear() { mask_ = 0; }
76:     void Mark(std::uint32_t slot) { if (slot < 32) mask_ |= (1u << slot); }
77:     bool IsShadow(std::uint32_t slot) const {
78:         return slot < 32 && (mask_ & (1u << slot)) != 0;
79:     }
80:     std::uint32_t Mask() const { return mask_; }
81: 
82: private:
83:     std::uint32_t mask_ = 0;
84: };
85: 
86: // Decide whether a register slot may receive the per-eye upload.
87: inline bool SlotMayRemap(const ShadowRegisterCensus& census, std::uint32_t slot,
88:                          bool isCameraMatrix) {
89:     return ShouldRemapRegister(isCameraMatrix, census.IsShadow(slot));
90: }
91: 
92: // --- optional: compensation if a future path offsets WORLD positions --------
93: // This mod remaps the camera clip matrices, so leaving the light matrix native
94: // is already exact. If a path ever offsets geometry in world space by `e`, the
95: // light matrix must be pre-compensated by the same world translation so both
96: // eyes still sample the native shadow:
97: //
98: //   column-vector convention (M * p):  L' = L * T(-e)
99: //   proof: L' * (p + e) = L * T(-e) * (p + e) = L * (p + e - e) = L * p
100: //
101: // Uses the Mat4/Vec3/Mul/Translation primitives from shadow_pass_policy.h.
102: inline bool CompensateWorldOffset(const Mat4& lightMatrix, Vec3 eyeOffsetWorldRedundant,
103:                                   Mat4& out) {
104:     // The argument is the geometry offset; we translate the light matrix the
105:     // other way so a point drawn at (p + e) projects as if it were at p.
106:     const Vec3 t{-eyeOffsetWorldRedundant.x, -eyeOffsetWorldRedundant.y,
107:                  -eyeOffsetWorldRedundant.z};
108:     for (float v : {t.x, t.y, t.z})
109:         if (!std::isfinite(v)) return false;
110:     out = Mul(lightMatrix, Translation(t));
111:     return true;
112: }
113: 
114: } // namespace singularity::shadow

