57: // atlases from the manifest when they land; the clipId mapping is identical.
58: // ---------------------------------------------------------------------------
59: inline bool MakeBlobTexture(IDirect3DDevice9* dev, D3DCOLOR rgb, float alphaScale,
60:                             int cols, int rows, int cell, IDirect3DTexture9** out) {
61:     if (out) *out = nullptr;
62:     if (!dev || !out || cols <= 0 || rows <= 0 || cell <= 0) return false;
63:     const UINT size = static_cast<UINT>(cols * cell);
64:     if (FAILED(dev->CreateTexture(size, size, 1, 0, D3DFMT_A8R8G8B8, D3DPOOL_MANAGED,
65:                                   out, nullptr)) || !*out)
66:         return false;
67: 
68:     D3DLOCKED_RECT lr;
69:     if (FAILED((*out)->LockRect(0, &lr, nullptr, 0))) {
70:         (*out)->Release(); *out = nullptr; return false;
71:     }
72:     const int total = cols * rows;
73:     const float inv = (cell > 1) ? 1.0f / static_cast<float>(cell - 1) : 0.0f;
74:     for (int y = 0; y < static_cast<int>(size); ++y) {
75:         DWORD* row = reinterpret_cast<DWORD*>(reinterpret_cast<BYTE*>(lr.pBits) +
76:                                               static_cast<size_t>(y) * lr.Pitch);
77:         const int cy = y / cell;
78:         for (int x = 0; x < static_cast<int>(size); ++x) {
79:             const int cx = x / cell;
80:             const int frame = cy * cols + cx;
81:             const float lx = static_cast<float>(x % cell) * inv * 2.0f - 1.0f;
82:             const float ly = static_cast<float>(y % cell) * inv * 2.0f - 1.0f;
83:             const float r = std::sqrt(lx * lx + ly * ly);
84:             const float t = (total > 1) ? static_cast<float>(frame) / (total - 1) : 0.0f;
85:             const float radius = 0.35f + 0.60f * t;
86:             float a = 1.0f - (r - radius * 0.35f) / (radius * 0.65f);
87:             if (a < 0.0f) a = 0.0f;
88:             if (a > 1.0f) a = 1.0f;
89:             a = a * a * (3.0f - 2.0f * a);            // smoothstep
90:             const BYTE A = static_cast<BYTE>(a * 255.0f * alphaScale);
91:             row[x] = (static_cast<DWORD>(A) << 24) | (rgb & 0x00FFFFFFu);
92:         }
93:     }
94:     (*out)->UnlockRect(0);
95:     return true;
96: }
