221: // Draws a list of DrawItems as world-space camera-facing quads. Must be called
222: // inside each eye's world draw. `camRight`/`camUp` are the world-space camera
223: // basis from that eye's view matrix.
224: class VfxDrawer {
225: public:
226:     static constexpr int kMaxBatchVerts = 6 * 64;   // 64 quads per flush
227: 
228:     bool Init(IDirect3DDevice9* dev) {
229:         if (vb_ || !dev) return vb_ != nullptr;
230:         const UINT bytes = sizeof(VfxVertex) * kMaxBatchVerts;
231:         if (FAILED(dev->CreateVertexBuffer(bytes, D3DUSAGE_DYNAMIC | D3DUSAGE_WRITEONLY,
232:                                            kVfxFvf, D3DPOOL_DEFAULT, &vb_, nullptr))) {
233:             vb_ = nullptr;
234:             return false;
235:         }
236:         return true;
237:     }
238: 
239:     void Shutdown() {
240:         if (vb_) { vb_->Release(); vb_ = nullptr; }
241:     }
242: 
243:     void DrawItems(IDirect3DDevice9* dev, const VfxDrawItem* items, int count,
244:                    const VfxAtlas& atlas, const float camRight[3], const float camUp[3]) {
245:         if (!dev || !items || count <= 0 || !vb_) return;
246: 
247:         VfxSavedState saved;
248:         SaveVfxState(dev, saved);
249: 
250:         dev->SetVertexShader(nullptr);
251:         dev->SetPixelShader(nullptr);
252:         dev->SetVertexDeclaration(nullptr);
253:         dev->SetRenderState(D3DRS_LIGHTING, FALSE);
254:         dev->SetRenderState(D3DRS_FOGENABLE, FALSE);
255:         dev->SetRenderState(D3DRS_CULLMODE, D3DCULL_NONE);
256:         dev->SetRenderState(D3DRS_ZENABLE, TRUE);
257:         dev->SetRenderState(D3DRS_ZWRITEENABLE, FALSE);
258:         dev->SetRenderState(D3DRS_ALPHATESTENABLE, FALSE);
259:         dev->SetTextureStageState(0, D3DTSS_COLOROP, D3DTOP_MODULATE);
260:         dev->SetTextureStageState(0, D3DTSS_COLORARG1, D3DTA_TEXTURE);
261:         dev->SetTextureStageState(0, D3DTSS_COLORARG2, D3DTA_DIFFUSE);
262:         dev->SetTextureStageState(0, D3DTSS_ALPHAOP, D3DTOP_MODULATE);
