26: inline bool ReadWholeFile(const char* path, std::vector<uint8_t>& out) {
27:     FILE* f = nullptr;
28:     if (fopen_s(&f, path, "rb") != 0 || !f) return false;
29:     fseek(f, 0, SEEK_END);
30:     const long n = ftell(f);
31:     fseek(f, 0, SEEK_SET);
32:     if (n <= 0) { fclose(f); return false; }
33:     out.resize(static_cast<size_t>(n));
34:     const size_t got = fread(out.data(), 1, out.size(), f);
35:     fclose(f);
36:     return got == out.size();
37: }
