39: // Minimal DDS uploader for DXT1/DXT5 with an arbitrary mip count.
40: inline bool LoadDdsTexture(IDirect3DDevice9* dev, const uint8_t* b, size_t n,
41:                            IDirect3DTexture9** out) {
42:     if (out) *out = nullptr;
43:     if (!dev || !b || n < 128 || std::memcmp(b, "DDS ", 4) != 0) return false;
44: 
45:     const UINT height = *reinterpret_cast<const UINT*>(b + 12);
46:     const UINT width = *reinterpret_cast<const UINT*>(b + 16);
47:     UINT mips = *reinterpret_cast<const UINT*>(b + 28);
48:     const DWORD pfFlags = *reinterpret_cast<const DWORD*>(b + 80);
49:     const uint32_t fourcc = *reinterpret_cast<const uint32_t*>(b + 84);
50:     if (mips == 0) mips = 1;
51: 
52:     D3DFORMAT fmt;
53:     int blk;
54:     if ((pfFlags & 0x4) && fourcc == MAKEFOURCC('D', 'X', 'T', '1')) { fmt = D3DFMT_DXT1; blk = 8; }
55:     else if ((pfFlags & 0x4) && fourcc == MAKEFOURCC('D', 'X', 'T', '5')) { fmt = D3DFMT_DXT5; blk = 16; }
56:     else return false;
57: 
58:     if (FAILED(dev->CreateTexture(width, height, mips, 0, fmt, D3DPOOL_MANAGED, out, nullptr)) || !*out)
59:         return false;
60: 
61:     size_t off = 128;
62:     for (UINT i = 0; i < mips; ++i) {
63:         const UINT mw = (width >> i) ? (width >> i) : 1;
64:         const UINT mh = (height >> i) ? (height >> i) : 1;
65:         const size_t rowbytes = static_cast<size_t>((mw + 3) / 4) * blk;
66:         const UINT rows = (mh + 3) / 4;
67:         const size_t need = rowbytes * rows;
68:         if (off + need > n) { (*out)->Release(); *out = nullptr; return false; }
69: 
70:         D3DLOCKED_RECT lr;
71:         if (FAILED((*out)->LockRect(i, &lr, nullptr, 0))) { (*out)->Release(); *out = nullptr; return false; }
72:         for (UINT y = 0; y < rows; ++y)
73:             std::memcpy(static_cast<uint8_t*>(lr.pBits) + static_cast<size_t>(y) * lr.Pitch,
74:                         b + off + static_cast<size_t>(y) * rowbytes, rowbytes);
75:         (*out)->UnlockRect(i);
76:         off += need;
77:     }
78:     return true;
79: }
