# Localized left/right asymmetry: find rows/columns where the two eyes differ most
$files = @('capture_2026-10-08_14-13-53.bmp','capture_2026-10-08_14-42-37.bmp','capture_2026-10-08_14-43-00.bmp','capture_2026-10-08_15-09-24.bmp')
$src = 'C:\Users\Trilex\AppData\Local\SingularityVR'
foreach ($f in $files) {
  if (-not (Test-Path "$src\$f")) { continue }
  $b = New-Object System.Drawing.Bitmap "$src\$f"
  $w = $b.Width; $h = $b.Height; $half = [int]($w/2)
  # sample a coarse grid, compare L vs R per cell
  $cell = 64; $maxDiff = 0; $maxY = 0; $maxX = 0
  for ($y=0; $y -lt $h; $y+=$cell) {
    for ($x=0; $x -lt $half; $x+=$cell) {
      $sumL=0.0; $sumR=0.0; $cnt=0
      for ($dy=0; $dy -lt $cell -and ($y+$dy) -lt $h; $dy+=8) {
        for ($dx=0; $dx -lt $cell -and ($x+$dx) -lt $half; $dx+=8) {
          $pL = $b.GetPixel($x+$dx, $y+$dy); $pR = $b.GetPixel($x+$half+$dx, $y+$dy)
          $sumL += ($pL.R*0.299 + $pL.G*0.587 + $pL.B*0.114)
          $sumR += ($pR.R*0.299 + $pR.G*0.587 + $pR.B*0.114)
          $cnt++
        }
      }
      if ($cnt -gt 0) {
        $d = [Math]::Abs(($sumL-$sumR)/$cnt)
        if ($d -gt $maxDiff) { $maxDiff = $d; $maxY = $y; $maxX = $x }
      }
    }
  }
  Write-Host ("{0}: max L/R cell diff={1:N1} at x={2} y={3} (frame {4}x{5})" -f $f, $maxDiff, $maxX, $maxY, $w, $h)
  $b.Dispose()
}

