+                    const D3DCOLOR col = 0xFFFFFFFF;
+                    VfxOverlayVtx v[4] = {
+                        { SX(cl[0]), SY(cl[0]), 0, 1, col, u0,      v0 + dv },
+                        { SX(cl[1]), SY(cl[1]), 0, 1, col, u0 + du, v0 + dv },
+                        { SX(cl[2]), SY(cl[2]), 0, 1, col, u0,      v0 },
+                        { SX(cl[3]), SY(cl[3]), 0, 1, col, u0 + du, v0 },
+                    };
