+    dev->SetRenderState(D3DRS_ALPHABLENDENABLE, oldAB);
+    dev->SetRenderState(D3DRS_ZENABLE, oldZ);
+    dev->SetFVF(oldFVF);
+    dev->SetPixelShader(oldPS);
+    dev->SetVertexShader(oldVS);
